     // ...
+    #[error("request timed out")]
+    Timeout,
+    #[error("rpc response has neither result nor error")]
+    Malformed,
-    #[error("retries exhausted")]
-    Exhausted,
+    #[error("retries exhausted, last error: {0}")]
+    Exhausted(String),
 }
```

