## Patch

### `src/fetch.rs`

```rust
#[derive(Debug, thiserror::Error)]
pub enum FetchError {
    #[error("rate limited")]
    RateLimited,
    #[error("request timed out")]
    Timeout,
    #[error("http status {0}")]
    Status(StatusCode),
    #[error("rpc error {code}: {message}")]
    Rpc { code: i64, message: String },
    #[error("malformed response: {0}")]
    Malformed(String),
    #[error(transparent)]
    Http(#[from] reqwest::Error),
    #[error("gave up after {attempts} attempts: {source}")]
    Exhausted { attempts: u32, source: Box<FetchError> },
}

impl FetchError {
    /// 重发同一个请求有没有意义
    pub fn is_retryable(&self) -> bool {
        match self {
            FetchError::RateLimited | FetchError::Timeout | FetchError::Http(_) => true,
            // -32603 internal / -32000 server error 是暂时的；
            // -32602 invalid params、结果集超限这类重试多少次都一样
            FetchError::Rpc { code, .. } => matches!(code, -32603 | -32000),
            FetchError::Status(s) => s.is_server_error(),
            FetchError::Malformed(_) | FetchError::Exhausted { .. } => false,
        }
    }

    pub fn kind(&self) -> &'static str {
        match self {
            FetchError::RateLimited => "rate_limited",
            FetchError::Timeout => "timeout",
            FetchError::Status(_) => "status",
            FetchError::Rpc { .. } => "rpc",
            FetchError::Malformed(_) => "malformed",
            FetchError::Http(_) => "http",
            FetchError::Exhausted { .. } => "exhausted",
        }
    }
}

pub async fn fetch_logs(client: &Client, from: u64, to: u64) -> Result<Vec<RawLog>, FetchError> {
    let body = json!({
        "jsonrpc": "2.0", "id": 1, "method": "eth_getLogs",
        "params": [{ "fromBlock": hex(from), "toBlock": hex(to) }],
    });

    metrics::counter!("rpc_requests_total").increment(1);

    let resp = match client.post(&CFG.rpc_url).json(&body).send().await {
        Ok(resp) => resp,
        // 超时 = 不知道这个 range 有没有 log。绝不能当成"抓到 0 条"往下传：
        // 那样 with_retry 会直接放行，writer 会把它标成 done，range 就永久丢了。
        Err(e) if e.is_timeout() => return Err(timeout(from, to, "send")),
        Err(e) => {
            metrics::counter!("fetch_errors_total", "kind" => "http").increment(1);
            return Err(FetchError::Http(e));
        }
    };

    // 网关的 429 / 5xx 经常不是合法 JSON-RPC，先按状态码分流，
    // 否则会掉进 json() 解析失败、被误判成不可重试的 Malformed
    let status = resp.status();
    if status == StatusCode::TOO_MANY_REQUESTS {
        metrics::counter!("fetch_errors_total", "kind" => "rate_limited").increment(1);
        return Err(FetchError::RateLimited);
    }
    if !status.is_success() {
        metrics::counter!("fetch_errors_total", "kind" => "status").increment(1);
        return Err(FetchError::Status(status));
    }

    // 一个 range 平均 ~10600 条 log，响应体好几 MB，读 body 期间同样会超时
    let v: RpcResponse<Vec<RawLog>> = match resp.json().await {
        Ok(v) => v,
        Err(e) if e.is_timeout() => return Err(timeout(from, to, "body")),
        Err(e) => {
            metrics::counter!("fetch_errors_total", "kind" => "decode").increment(1);
            return Err(FetchError::Malformed(e.to_string()));
        }
    };

    if let Some(err) = v.error {
        metrics::counter!("fetch_errors_total", "kind" => "rpc").increment(1);
        if err.code == -32005 {
            return Err(FetchError::RateLimited);
        }
        return Err(FetchError::Rpc { code: err.code, message: err.message });
    }

    // result 缺失 ≠ 空结果。原来的 unwrap_or_default() 和超时那条是同一类 bug：
    // 把"不知道"编码成了"0 条"。真正的空结果是 "result": []，会反序列化成 Some(vec![])，
    // 所以这里不会误伤合法的空 range。
    v.result.ok_or_else(|| {
        metrics::counter!("fetch_errors_total", "kind" => "malformed").increment(1);
        FetchError::Malformed("response carried neither result nor error".into())
    })
}

fn timeout(from: u64, to: u64, stage: &'static str) -> FetchError {
    warn!(from, to, stage, "request timed out; will retry, NOT recorded as empty");
    metrics::counter!("rpc_timeouts_total").increment(1);
    metrics::counter!("fetch_errors_total", "kind" => "timeout").increment(1);
    FetchError::Timeout
}
```

### `src/retry.rs`

```rust
const MAX_BACKOFF: Duration = Duration::from_secs(30);

pub async fn with_retry<F, Fut, T>(mut f: F) -> Result<T, FetchError>
where
    F: FnMut() -> Fut,
    Fut: Future<Output = Result<T, FetchError>>,
{
    let mut delay = Duration::from_millis(200);
    let mut attempt: u32 = 0;

    loop {
        let err = match f().await {
            Ok(v) => return Ok(v),
            Err(e) => e,
        };

        // 重发救不回来的错误立刻上抛，别白烧配额
        if !err.is_retryable() {
            metrics::counter!("fetch_abandoned_total", "kind" => err.kind()).increment(1);
            return Err(err);
        }

        if attempt >= CFG.max_retries {
            metrics::counter!("fetch_exhausted_total", "kind" => err.kind()).increment(1);
            // 返回 Err 是整个修复的落点：调用方拿到 Err 就不写 ranges_done，
            // range 留在"没做完"状态，下一轮 verify 会当成 gap 报出来。
            // 原来这里返回的 Exhausted 丢掉了底层错误，排查时看不出是超时还是限流。
            return Err(FetchError::Exhausted { attempts: attempt + 1, source: Box::new(err) });
        }

        attempt += 1;
        metrics::counter!("retries_total", "kind" => err.kind()).increment(1);
        warn!(?err, attempt, "retrying");

        // 24 个 worker 撞上同一波限流会同步退避，加 jitter 打散；delay 封顶 30s
        let jitter = Duration::from_millis(
            rand::thread_rng().gen_range(0..=(delay.as_millis() as u64 / 2).max(1)),
        );
        tokio::time::sleep(delay + jitter).await;
        delay = (delay * 2).min(MAX_BACKOFF);
    }
}
```

原版还有个小问题顺手修了：`Err(FetchError::RateLimited)` 那个分支排在 `attempt < max_retries` 守卫**前面**，所以最后一次迭代遇到限流会先白睡一觉再返回 `Exhausted`。

### `src/writer.rs`

```rust
#[derive(Debug, thiserror::Error)]
pub enum WriteError {
    #[error(transparent)]
    Db(#[from] sqlx::Error),
    #[error("COPY row count mismatch for {from}-{to}: encoded {expected}, postgres took {copied}")]
    CopyCountMismatch { from: u64, to: u64, expected: u64, copied: u64 },
}

/// 只有 fetch 成功返回的 logs 才能走到这里。
/// 调用方必须保证：with_retry 返回 Err 时不调用本函数。
pub async fn write_range(
    tx: &mut Transaction<'_, Postgres>,
    from: u64,
    to: u64,
    logs: &[Log],
) -> Result<u64, WriteError> {
    // 这个 range 以前写过吗？写过就是重灌（修坏 range、或 verify 重新排进来的），
    // 必须先清旧行，否则重灌 = 数据翻倍而不是覆盖。首灌时这次查询是一次主键命中。
    // FOR UPDATE 顺手锁住这行，避免两个 worker 同时重灌同一段。
    let previous: Option<(i64,)> = sqlx::query_as(
        "SELECT row_count FROM ranges_done WHERE from_block = $1 FOR UPDATE",
    )
    .bind(from as i64)
    .fetch_optional(&mut **tx)
    .await?;

    if let Some((prev_count,)) = previous {
        let deleted = sqlx::query("DELETE FROM logs WHERE block_number BETWEEN $1 AND $2")
            .bind(from as i64)
            .bind(to as i64)
            .execute(&mut **tx)
            .await?
            .rows_affected();
        info!(from, to, prev_count, deleted, "re-ingesting range");
        metrics::counter!("range_reingested_total").increment(1);
    }

    let copied: u64 = if logs.is_empty() {
        0
    } else {
        let mut copy = tx.copy_in_raw(
            "COPY logs (block_number, tx_index, log_index, address, topic0, topics, data) \
             FROM STDIN WITH (FORMAT csv)",
        ).await?;
        copy.send(encode_csv(logs).as_bytes()).await?;
        let n = copy.finish().await?;          // Postgres 实际收下的行数
        metrics::counter!("copy_batches_total").increment(1);
        metrics::counter!("logs_written_total").increment(n);
        n
    };

    // row_count 记 Postgres 报回来的数，不是 logs.len()。
    // 对不上说明 encode_csv 丢了行 —— 返回 Err 让整个事务回滚，不要 panic：
    // 24 个 worker 里 panic 掉一个，这个 range 只会换一种方式悄悄消失。
    if copied != logs.len() as u64 {
        return Err(WriteError::CopyCountMismatch {
            from, to, expected: logs.len() as u64, copied,
        });
    }

    sqlx::query(
        "INSERT INTO ranges_done (from_block, to_block, row_count, finished_at) \
         VALUES ($1, $2, $3, now()) \
         ON CONFLICT (from_block) DO UPDATE SET \
             to_block    = EXCLUDED.to_block, \
             row_count   = EXCLUDED.row_count, \
             finished_at = EXCLUDED.finished_at",
    )
    .bind(from as i64)
    .bind(to as i64)
    .bind(copied as i64)
    .execute(&mut **tx)
    .await?;

    info!(from, to, rows = copied, "range done");
    Ok(copied)
}
```

### `src/verify.rs`

```rust
#[derive(Debug, Default)]
pub struct VerifyReport {
    /// ranges_done 完全没覆盖到的区段
    pub gaps: Vec<(u64, u64)>,
    /// 覆盖到了但 row_count = 0。Base mainnet 上连续 128 个区块一条 log 都没有
    /// 基本不可能，所以一律按"没抓到"处理，而不是"真的是空的"。
    pub suspicious: Vec<(u64, u64)>,
}

impl VerifyReport {
    pub fn to_requeue(&self) -> Vec<(u64, u64)> {
        self.gaps.iter().chain(&self.suspicious).copied().collect()
    }
}

pub async fn verify(pool: &PgPool, start: u64, head: u64) -> Result<VerifyReport, sqlx::Error> {
    // 原来这里是 .unwrap()：PG 抖一下整个夜间审计就 panic，
    // 连覆盖率报告都拿不到 —— 2.9% 的洞能藏好几天，这也是原因之一。
    let rows = sqlx::query_as::<_, (i64, i64, i64)>(
        "SELECT from_block, to_block, row_count FROM ranges_done ORDER BY from_block",
    )
    .fetch_all(pool)
    .await?;

    let mut report = VerifyReport::default();
    let mut cursor = start;

    for (f, t, row_count) in rows {
        let (f, t) = (f as u64, t as u64);
        if f > cursor {
            report.gaps.push((cursor, f - 1));
        }
        if row_count == 0 && t >= start && f <= head {
            report.suspicious.push((f, t));
        }
        cursor = cursor.max(t + 1);
    }
    if cursor <= head {
        report.gaps.push((cursor, head));
    }

    metrics::gauge!("verify_gap_ranges").set(report.gaps.len() as f64);
    metrics::gauge!("verify_suspicious_ranges").set(report.suspicious.len() as f64);

    if !report.suspicious.is_empty() {
        error!(n = report.suspicious.len(), "ranges marked done with zero rows");
    }
    Ok(report)
}
```

运维上加一条：同一个 range 连续两晚出现在 `suspicious` 里就告警，别让它每晚静默重排。

### `src/normalize.rs`（同一类问题，顺手一起修）

那两个 `unwrap()` 会在响应字段畸形时 panic 掉 worker——症状和这次一模一样，range 无声消失：

```rust
#[derive(Debug, thiserror::Error)]
#[error("bad hex in field `{field}`: {value:?}")]
pub struct NormalizeError { pub field: &'static str, pub value: String }

fn parse_hex<T: TryFrom<u64>>(field: &'static str, s: &str) -> Result<T, NormalizeError> {
    u64::from_str_radix(s.trim_start_matches("0x"), 16)
        .ok()
        .and_then(|v| T::try_from(v).ok())
        .ok_or_else(|| NormalizeError { field, value: s.to_owned() })
}

pub fn normalize(raw: Vec<RawLog>) -> Result<Vec<Log>, NormalizeError> {
    raw.into_iter()
        // 先过滤再解析：reorg 掉的 log 本来就要丢，没必要为它的字段解析失败整批报错
        .filter(|r| !r.removed)
        .map(|r| {
            Ok(Log {
                block_number: parse_hex("blockNumber", &r.block_number)?,
                // 原来 and_then(...).unwrap_or_default() 会把畸形的 txIndex 悄悄变成 0；
                // 字段缺失（pending log）仍然按 0 处理，字段畸形则报错
                tx_index: r.transaction_index.as_deref()
                    .map(|s| parse_hex("transactionIndex", s))
                    .transpose()?
                    .unwrap_or_default(),
                log_index: parse_hex("logIndex", &r.log_index)?,
                address: r.address.to_lowercase(),
                topic0: r.topics.first().cloned().unwrap_or_default(),
                topics: r.topics,
                data: hex_decode(&r.data),
                removed: r.removed,
            })
        })
        .collect()
}
```

