#[derive(Debug, thiserror::Error)]
pub enum FetchError {
    #[error("rpc 限流")]
    RateLimited,
    #[error("请求超时")]
    Timeout,                                    // 新增
    #[error("rpc 返回成功但没有 result 字段")]
    MalformedResponse,                          // 新增
    #[error("rpc 错误: {0}")]
    Rpc(String),
    #[error(transparent)]
    Http(#[from] reqwest::Error),
    #[error("重试耗尽")]
    Exhausted,
}

impl FetchError {
    /// 只有"重试一次可能就好了"的错误才返回 true。
    /// Rpc(_) 不在内 —— 比如 "query returned more than 10000 results"
    /// 重试 5 次也不会变好，应该直接报出来让人看见。
    pub fn is_retryable(&self) -> bool {
        matches!(
            self,
            FetchError::RateLimited
                | FetchError::Timeout
                | FetchError::MalformedResponse
                | FetchError::Http(_)
        )
    }
}
