```rust
pub async fn fetch_logs(client: &Client, from: u64, to: u64) -> Result<Vec<RawLog>, FetchError> {
    let body = json!({
        "jsonrpc": "2.0", "id": 1, "method": "eth_getLogs",
        "params": [{ "fromBlock": hex(from), "toBlock": hex(to) }],
    });

    match client.post(&CFG.rpc_url).json(&body).send().await {
        Ok(resp) => {
            let v: RpcResponse<Vec<RawLog>> = resp.json().await?;
            if let Some(err) = v.error {
                if err.code == -32005 {
                    return Err(FetchError::RateLimited);
                }
                return Err(FetchError::Rpc(err.message));
            }
            // result 缺失 != 空结果。JSON-RPC 成功响应必须带 result，
            // 缺了说明响应有问题，不能当成"这段没有 log"。
            v.result.ok_or(FetchError::MalformedResponse)
        }
        Err(e) if e.is_timeout() => {
            // 超时是失败，不是空结果。返回 Err 让 with_retry 重试；
            // 重试全挂掉的话由调用方决定，绝不能让 range 被标成 done。
            warn!(from, to, "请求超时，将重试");
            metrics::counter!("rpc_timeouts_total").increment(1);
            metrics::counter!("fetch_errors_total").increment(1);
            Err(FetchError::Timeout)
        }
        Err(e) => {
            metrics::counter!("fetch_errors_total").increment(1);
            Err(FetchError::Http(e))
        }
    }
}
```

### `src/retry.rs`

```rust
pub async fn with_retry<F, Fut, T>(mut f: F) -> Result<T, FetchError>
where
    F: FnMut() -> Fut,
    Fut: Future<Output = Result<T, FetchError>>,
{
    const MAX_DELAY: Duration = Duration::from_secs(30);
    let mut delay = Duration::from_millis(200);

    for attempt in 0..=CFG.max_retries {
        match f().await {
            Ok(v) => return Ok(v),
            // 可重试 且 还有次数 —— 退避后再来
            Err(e) if e.is_retryable() && attempt < CFG.max_retries => {
                metrics::counter!("retries_total").increment(1);
                warn!(?e, attempt, "retrying");
                tokio::time::sleep(jitter(delay)).await;
                delay = (delay * 2).min(MAX_DELAY);
            }
            // 不可重试，或次数用完 —— 把真实错误原样抛出去，
            // 不要退化成 Exhausted，不然上面看不出到底是什么挂了
            Err(e) => return Err(e),
        }
    }
    unreachable!("循环只能通过 return 退出")
}

/// 等量抖动。24 个 worker 同步退避会把限流窗口打成脉冲。
fn jitter(d: Duration) -> Duration {
    let half = d.as_millis() as u64 / 2;
    Duration::from_millis(half + rand::random::<u64>() % (half + 1))
}
```

原来那个 `Err(FetchError::RateLimited)` 分支不判 `attempt`，最后一次还会白睡一觉再退出，一并修掉了。

### `src/normalize.rs`

```rust
#[derive(Debug, thiserror::Error)]
pub enum NormalizeError {
    #[error("第 {index} 条 log 的 {field} 字段无法解析: {value:?}")]
    BadField { index: usize, field: &'static str, value: String },
    #[error("第 {index} 条 log 缺少 {field} 字段")]
    MissingField { index: usize, field: &'static str },
}

fn parse_hex<T: TryFrom<u64>>(s: &str) -> Option<T> {
    u64::from_str_radix(s.trim_start_matches("0x"), 16)
        .ok()
        .and_then(|v| T::try_from(v).ok())
}

pub fn normalize(raw: Vec<RawLog>) -> Result<Vec<Log>, NormalizeError> {
    let mut out = Vec::with_capacity(raw.len());
    let mut removed_count = 0usize;

    for (index, r) in raw.into_iter().enumerate() {
        if r.removed {
            removed_count += 1;
            continue;
        }

        let block_number = parse_hex::<u64>(&r.block_number).ok_or_else(|| {
            NormalizeError::BadField { index, field: "blockNumber", value: r.block_number.clone() }
        })?;
        let log_index = parse_hex::<u32>(&r.log_index).ok_or_else(|| {
            NormalizeError::BadField { index, field: "logIndex", value: r.log_index.clone() }
        })?;
        // 不能 unwrap_or_default：tx_index 默认成 0 会静默污染排序键。
        // 已确认区块里这个字段一定有，缺了就是响应有问题。
        let tx_index = match r.transaction_index.as_deref() {
            Some(s) => parse_hex::<u32>(s).ok_or_else(|| NormalizeError::BadField {
                index, field: "transactionIndex", value: s.to_string(),
            })?,
            None => return Err(NormalizeError::MissingField { index, field: "transactionIndex" }),
        };

        out.push(Log {
            block_number,
            tx_index,
            log_index,
            address: r.address.to_lowercase(),
            topic0: r.topics.first().cloned().unwrap_or_default(),
            topics: r.topics,
            data: hex_decode(&r.data),
            removed: false,
        });
    }

    // 回填的是已终结区块，这里本该恒为 0。不为 0 说明在追 unsafe head，
    // 要看得见，不能像以前那样被 filter 悄悄吃掉。
    if removed_count > 0 {
        metrics::counter!("normalize_removed_dropped_total").increment(removed_count as u64);
        warn!(removed_count, "已终结区间里出现 removed=true 的 log");
    }

    Ok(out)
}
```

### `src/writer.rs`

```rust
#[derive(Debug, thiserror::Error)]
pub enum WriteError {
    #[error(transparent)]
    Db(#[from] sqlx::Error),
    #[error("range {from}..={to} 为空 —— 上游多半吞了错误，拒绝标记为 done")]
    UnexpectedEmptyRange { from: u64, to: u64 },
    #[error("range {from}..={to}: COPY 写入 {copied} 行，期望 {expected} 行")]
    CopyRowMismatch { from: u64, to: u64, expected: u64, copied: u64 },
}

pub async fn write_range(
    tx: &mut Transaction<'_, Postgres>,
    from: u64,
    to: u64,
    logs: &[Log],
) -> Result<(), WriteError> {
    // 纵深防御：Base 上 128 个区块 ≈ 4 分钟，不可能一条 log 都没有。
    // 就算 fetch 层将来又有人改回吞错误，这里也会把 range 拦下来。
    if logs.is_empty() && !CFG.allow_empty_ranges {
        return Err(WriteError::UnexpectedEmptyRange { from, to });
    }

    // 幂等：重灌同一个 range 前先清掉旧行，否则 verifier 补数会灌出重复。
    // 需要 logs(block_number) 上有索引；首次回填时这里是一次返回 0 行的索引探测。
    sqlx::query("DELETE FROM logs WHERE block_number BETWEEN $1 AND $2")
        .bind(from as i64)
        .bind(to as i64)
        .execute(&mut **tx)
        .await?;

    if !logs.is_empty() {
        let mut copy = tx.copy_in_raw(
            "COPY logs (block_number, tx_index, log_index, address, topic0, topics, data) \
             FROM STDIN WITH (FORMAT csv)"
        ).await?;
        copy.send(encode_csv(logs).as_bytes()).await?;
        let copied = copy.finish().await?;
        if copied != logs.len() as u64 {
            // 返回 Err 而不是 panic：事务在 drop 时回滚，这个 range 保持未完成，
            // 其余 23 个 worker 继续跑。panic 会连带丢掉所有在途 range。
            return Err(WriteError::CopyRowMismatch {
                from, to, expected: logs.len() as u64, copied,
            });
        }
        metrics::counter!("copy_batches_total").increment(1);
    }

    sqlx::query(
        "INSERT INTO ranges_done (from_block, to_block, row_count, finished_at) \
         VALUES ($1, $2, $3, now()) \
         ON CONFLICT (from_block) DO UPDATE SET \
             to_block    = EXCLUDED.to_block, \
             row_count   = EXCLUDED.row_count, \
             finished_at = EXCLUDED.finished_at"
    )
    .bind(from as i64)
    .bind(to as i64)
    .bind(logs.len() as i64)
    .execute(&mut **tx)
    .await?;

    info!(from, to, rows = logs.len(), "range done");
    Ok(())
}
```

### `src/verify.rs`

```rust
pub async fn verify(pool: &PgPool, start: u64, head: u64) -> Result<Vec<(u64, u64)>, sqlx::Error> {
    let rows = sqlx::query_as::<_, (i64, i64, i64)>(
        "SELECT from_block, to_block, row_count FROM ranges_done ORDER BY from_block"
    )
    .fetch_all(pool)
    .await?;          // 原来这里是 unwrap()，verifier 挂掉会静默变成"没有 gap"

    let mut gaps = Vec::new();
    let mut cursor = start;

    for (f, t, row_count) in rows {
        let (f, t) = (f as u64, t as u64);

        // 1) 没被覆盖到的段
        if f > cursor {
            gaps.push((cursor, f - 1));
        }

        // 2) 标了 done 但零行 —— 本轮修完后不该再出现，留作兜底网
        if row_count == 0 && t >= start && f <= head {
            warn!(from = f, to = t, "range 标记为 done 但 row_count=0，重新回灌");
            metrics::counter!("verify_empty_ranges_total").increment(1);
            gaps.push((f.max(start), t.min(head)));
        }

        cursor = cursor.max(t + 1);
    }

    if cursor <= head {
        gaps.push((cursor, head));
    }

    gaps.sort_unstable();   // 零行 range 是插在已覆盖区间里的，顺序会乱
    Ok(gaps)
}
```

