```rust
/// 超时就把 range 对半切，直到单块为止。非超时错误直接上抛。
pub async fn fetch_logs_splitting(
    client: &Client,
    from: u64,
    to: u64,
) -> Result<Vec<RawLog>, FetchError> {
    let mut out = Vec::new();
    let mut stack = vec![(from, to)];

    while let Some((f, t)) = stack.pop() {
        match with_retry(|| fetch_logs(client, f, t)).await {
            Ok(v) => out.extend(v),
            Err(FetchError::Timeout { .. }) if t > f => {
                let mid = f + (t - f) / 2;
                metrics::counter!("range_splits_total").increment(1);
                warn!(from = f, to = t, mid, "splitting range after timeout");
                stack.push((mid + 1, t)); // 后进先出，左半边先跑，保持区块序
                stack.push((f, mid));
            }
            Err(e) => return Err(e),
        }
    }
    Ok(out)
}
```

worker 里把 `with_retry(|| fetch_logs(...))` 换成 `fetch_logs_splitting(...)`（别嵌套两层 retry）。单块还超时就真的抛错，range 不标 done，留给 verifier。

