#[derive(Debug, thiserror::Error)]
pub enum WriteError {
    #[error(transparent)]
    Db(#[from] sqlx::Error),
    #[error("range {from}..={to}: COPY wrote {actual} rows, expected {expected}")]
    RowCountMismatch { from: u64, to: u64, expected: u64, actual: u64 },
}

pub enum WriteMode {
    /// 正常前向回填，该 range 此前没有数据
    Append,
    /// 重灌，先清掉该 range 已有的行，保证可重入
    Replace,
}

pub async fn write_range(
    tx: &mut Transaction<'_, Postgres>,
    from: u64,
    to: u64,
    logs: &[Log],
    mode: WriteMode,
) -> Result<(), WriteError> {
    if matches!(mode, WriteMode::Replace) {
        let deleted = sqlx::query("DELETE FROM logs WHERE block_number BETWEEN $1 AND $2")
            .bind(from as i64)
            .bind(to as i64)
            .execute(&mut **tx)
            .await?
            .rows_affected();
        if deleted > 0 {
            warn!(from, to, deleted, "replacing existing rows");
        }
    }

    if !logs.is_empty() {
        let mut copy = tx.copy_in_raw(
            "COPY logs (block_number, tx_index, log_index, address, topic0, topics, data) \
             FROM STDIN WITH (FORMAT csv)"
        ).await?;
        copy.send(encode_csv(logs).as_bytes()).await?;
        let copied = copy.finish().await?;

        // 对不上就让整个 tx 回滚，range 不会被标 done —— 比写一个假的
        // row_count 好
        if copied != logs.len() as u64 {
            return Err(WriteError::RowCountMismatch {
                from, to, expected: logs.len() as u64, actual: copied,
            });
        }
    } else {
        // 修复后这里只可能是"这段真的没有 log"。这个计数器要是开始涨，
        // 说明又有东西在静默吞结果了。
        metrics::counter!("ranges_empty_total").increment(1);
    }

    sqlx::query(
        "INSERT INTO ranges_done (from_block, to_block, row_count, fetch_confirmed, finished_at) \
         VALUES ($1, $2, $3, true, now()) \
         ON CONFLICT (from_block) DO UPDATE SET \
             to_block        = EXCLUDED.to_block, \
             row_count       = EXCLUDED.row_count, \
             fetch_confirmed = true, \
             finished_at     = now()"
    )
    .bind(from as i64)
    .bind(to as i64)
    .bind(logs.len() as i64)
    .execute(&mut **tx)
    .await?;

    info!(from, to, rows = logs.len(), "range done");
    Ok(())
}
```

